package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Dfp_multiply_TriageGen2Test {

    private Dfp dfpInstance;

    @Before
    public void setUp() {
        // Initialize a Dfp instance using the field from a new instance
        dfpInstance = Dfp.newInstance();
    }

    @Test
    public void testMultiply_PositiveInteger() {
        Dfp val = Dfp.newInstance(5);
        Dfp result = val.multiply(3);
        // 5 * 3 = 15
        assertEquals(Dfp.newInstance(15), result);
    }

    @Test
    public void testMultiply_NegativeInteger() {
        Dfp val = Dfp.newInstance(-4);
        Dfp result = val.multiply(2);
        // -4 * 2 = -8
        assertEquals(Dfp.newInstance(-8), result);
    }

    @Test
    public void testMultiply_MultiplyByZero() {
        Dfp val = Dfp.newInstance(100);
        Dfp result = val.multiply(0);
        // 100 * 0 = 0
        assertEquals(Dfp.getZero(), result);
    }

    @Test
    public void testMultiply_ZeroByInteger() {
        Dfp val = Dfp.getZero();
        Dfp result = val.multiply(50);
        // 0 * 50 = 0
        assertEquals(Dfp.getZero(), result);
    }

    @Test
    public void testMultiply_NegativeByNegative() {
        Dfp val = Dfp.newInstance(-5);
        Dfp result = val.multiply(-2);
        // -5 * -2 = 10
        assertEquals(Dfp.newInstance(10), result);
    }

    @Test
    public void testMultiply_LargeInteger() {
        // Testing boundary/large integer behavior within int range
        Dfp val = Dfp.newInstance(10000);
        Dfp result = val.multiply(Integer.MAX_VALUE / 10000); 
        // Verification via math logic
        int multiplier = Integer.MAX_VALUE / 10000;
        assertEquals(Dfp.newInstance((long) 10000 * multiplier), result);
    }

    @Test
    public void testMultiply_One() {
        Dfp val = Dfp.newInstance(123);
        Dfp result = val.multiply(1);
        assertEquals(val, result);
    }

    @Test
    public void testMultiply_NegativeOne() {
        Dfp val = Dfp.newInstance(123);
        Dfp result = val.multiply(-1);
        assertEquals(Dfp.newInstance(-123), result);
    }

    @Test
    public void testMultiply_IdentityWithNegativeOne() {
        Dfp val = Dfp.newInstance(-123);
        Dfp result = val.multiply(-1);
        assertEquals(Dfp.newInstance(123), result);
    }
}
